// Minimal real Utilities.formatDate mock (America/New_York only; the only zone
// the script ever uses) so date/timezone logic is genuinely exercised rather
// than stubbed. Supports exactly the tokens the script calls with.
function formatDateET_(date,zone,pattern){
  if(zone!=='America/New_York')throw new Error('formatDateET_ mock only supports America/New_York');
  const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:zone,weekday:'short',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(date).map(p=>[p.type,p.value]));
  const hour24=parts.hour==='24'?'00':parts.hour,h12n=(Number(hour24)%12)||12,isoDow=({Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6,Sun:7})[parts.weekday];
  const tokens={EEE:parts.weekday,MM:parts.month,dd:parts.day,yyyy:parts.year,HH:hour24,H:String(Number(hour24)),mm:parts.minute,h:String(h12n),a:Number(hour24)<12?'AM':'PM',u:String(isoDow)};
  return pattern.replace(/EEE|yyyy|MM|dd|HH|H|mm|u|h|a/g,m=>tokens[m]);
}
