test('Phase 3 normalizes both provider formats without a fetch, Sheet write, or inferred identity',()=>{const e=setup(),sgo=JSON.parse(fs.readFileSync(path.join(__dirname,'..','work','raw','sports_game_odds_phase2_raw_latest.json'),'utf8')).data[0];e.ctx.sgo=sgo;e.ctx.oddsApi=payload();const sgoNormalized=JSON.parse(e.run('JSON.stringify(normalizeSportsGameOddsEvent_(sgo,"draftkings"))')),oddsNormalized=JSON.parse(e.run('JSON.stringify(normalizeOddsApiEvent_(oddsApi,"draftkings"))'));assert.equal(sgoNormalized.provider,'sportsgameodds');assert.equal(sgoNormalized.provider_event_id,'FznP2IcFgXu9TcHvvja3');assert.equal(sgoNormalized.home_team,'Buffalo Bills');assert.equal(sgoNormalized.away_team,'Detroit Lions');assert.equal(sgoNormalized.diagnostics.source_quote_count,28);assert.equal(sgoNormalized.quotes.length,16);assert.equal(sgoNormalized.unavailable_quotes.length,10);assert.equal(sgoNormalized.diagnostics.normalized_quote_count,16);assert.equal(sgoNormalized.diagnostics.unavailable_quote_count,12);assert.deepEqual(sgoNormalized.diagnostics.unsupported_stat_ids,[]);assert.ok(sgoNormalized.quotes.every(q=>q.available&&q.player_id&&q.player_team&&q.source_updated_utc&&['OVER','UNDER'].includes(q.side)));const palmer=sgoNormalized.quotes.find(q=>q.player==='Josh Palmer');assert.equal(palmer.player_key,'joshua palmer');assert.equal(oddsNormalized.provider,'the_odds_api');assert.equal(oddsNormalized.quotes.length,2);assert.equal(oddsNormalized.quotes[0].player_id,'');assert.equal(oddsNormalized.quotes[0].player_team,'');assert.equal(e.calls.length,0);assert.equal(e.sheet('INDEX').data.length,0);assert.throws(()=>e.run('normalizeSportsGameOddsEvent_({leagueID:"NFL",type:"match",eventID:"x",teams:{},status:{},odds:{}},"draftkings")'));});
test('Phase 5 line history preserves available and explicit-unavailable provider observations and is idempotent',()=>{const e=setup(),sgo=JSON.parse(fs.readFileSync(path.join(__dirname,'..','work','raw','sports_game_odds_phase2_raw_latest.json'),'utf8')).data[0];e.ctx.sgo=sgo;e.ctx.normalized=JSON.parse(e.run('JSON.stringify(normalizeSportsGameOddsEvent_(sgo,"draftkings"))'));const first=JSON.parse(e.run('JSON.stringify(recordNormalizedLineHistory_(normalized,"phase5_fixture_test"))'));assert.deepEqual(first,{observed:26,inserted:26,duplicates:0});const history=e.sheet('LINE_HISTORY').data;assert.equal(history.length,27);assert.equal(history[0][0],'History ID');assert.equal(history.slice(1).filter(r=>r[17]===false).length,10);assert.ok(history.slice(1).every(r=>r[18]==='phase5_fixture_test'));const second=JSON.parse(e.run('JSON.stringify(recordNormalizedLineHistory_(normalized,"phase5_fixture_test"))'));assert.deepEqual(second,{observed:26,inserted:0,duplicates:26});assert.equal(e.calls.length,0);});
