test('Phase 4 retains same-bookmaker duplicates, flags price and line differences, and refuses same-source duplicates',()=>{const e=setup(),base={league:'NFL',sport:'americanfootball_nfl',home_team:'Buffalo Bills',away_team:'Detroit Lions',kickoff_utc:'2026-09-18T00:15:00.000Z',bookmaker:'draftkings'},q=(id,player,line,side,price)=>({provider_quote_id:id,market_key:'player_pass_yds',player_key:player,player:player==='josh allen'?'Josh Allen':'Jared Goff',line:line,side:side,price:price,available:true,source_updated_utc:'2026-09-15T16:24:25.533Z'}),a=Object.assign({provider:'the_odds_api',provider_event_id:'odds-1'},base,{quotes:[q('a-over','josh allen',250.5,'OVER',-110),q('a-under','josh allen',250.5,'UNDER',-105),q('a-only','jared goff',260.5,'OVER',-110),q('a-line','jared goff',260.5,'UNDER',-110)]}),b=Object.assign({provider:'sportsgameodds',provider_event_id:'sgo-1'},base,{quotes:[q('b-over','josh allen',250.5,'OVER',-112),q('b-under','josh allen',250.5,'UNDER',-105),q('b-only','jared goff',260.5,'OVER',-110),q('b-line','jared goff',261.5,'UNDER',-110)]});e.ctx.a=a;e.ctx.b=b;const result=JSON.parse(e.run('JSON.stringify(crossProviderDiagnostics_(a,b))'));assert.equal(result.observations.length,8);assert.equal(result.summary.same_bookmaker_duplicate_observation_count,3);assert.equal(result.summary.price_agreement_count,2);assert.equal(result.summary.price_difference_count,1);assert.equal(result.summary.line_mismatch_count,1);assert.equal(result.summary.first_only_count,1);assert.equal(result.summary.second_only_count,1);assert.equal(result.exact_matches[0].first.provider,'the_odds_api');assert.equal(result.exact_matches[0].second.provider,'sportsgameodds');assert.equal(e.calls.length,0);const duplicate=JSON.parse(JSON.stringify(a));duplicate.quotes.push(q('a-duplicate','josh allen',250.5,'OVER',-110));e.ctx.duplicate=duplicate;assert.throws(()=>e.run('crossProviderDiagnostics_(duplicate,b)'),/Duplicate normalized quote/);});
