function mobileUi_(dashboard,plan){
 dashboard.app_build ||= '2026.10.07-logo.1';
 const html=fs.readFileSync(path.join(__dirname,'Mobile.html'),'utf8'),script=[...html.matchAll(/<script>([\s\S]*?)<\/script>/g)][0][1],elements={},calls=[],shared=[],pending={reviews:[]},intervals=new Map();let nextInterval=0,status={operation:null,last_export:null},deferReviews=false;
 function el(id){return elements[id]||= {id,className:'',textContent:'',innerHTML:'',hidden:false,getElementsByTagName(){return []},getElementsByClassName(){return []}};}
 const bridge={withSuccessHandler(ok){this.ok=ok;return this},withFailureHandler(fail){this.fail=fail;return this},mobileDashboard(){calls.push('dashboard');this.ok(dashboard)},mobileKeyPoolStatus(){this.ok({slots:[]})},mobileRefreshCreditBalances(){calls.push('credits');pending.credits={ok:this.ok,fail:this.fail}},mobilePrepareSelections(){calls.push('review');if(deferReviews){pending.reviews.push({ok:this.ok,fail:this.fail});return;}this.ok({plan})},mobileLoadAndExport(value,id){calls.push('load');pending.load={ok:this.ok,fail:this.fail,id,plan:value}},mobileRefreshScheduleAndOdds(value,id){calls.push('schedule');pending.schedule={ok:this.ok,fail:this.fail,id}},mobileOperationStatus(){calls.push('status');this.ok(status)},mobileClearOperationStatus(id){calls.push('clear');if(status.operation&&status.operation.state==='RUNNING'){this.ok(status);return;}status={operation:null,last_export:status.last_export};dashboard.operation=null;this.ok(status)}};
 const window={google:{script:{run:bridge}},navigator:{standalone:false,share(payload){shared.push(payload);return Promise.resolve()}},localStorage:{getItem(){return '1'}},matchMedia(){return {matches:false}},scrollTo(){},confirm(){return true},setInterval(fn,ms){const id=++nextInterval;intervals.set(id,{fn,ms});return id},clearInterval(id){intervals.delete(id)},setTimeout(){return 1},clearTimeout(){}};
 const document={getElementById:el,querySelector(){return {href:'icon'}}};
 vm.runInNewContext(script,{window,document,google:window.google,navigator:window.navigator,Date,Math,console});
 return {el,calls,shared,pending,intervals,setStatus(value){status=value},setDeferReviews(value){deferReviews=value}};
}
