function draft(prices){return {label:'Sunday Early',bookmaker:'DraftKings',stake:10,notes:'test',legs:prices.map((price,i)=>({eventId:'event'+i,game:'Away @ Home',subject:'Player '+i,market:'player_receptions',selection:'Over',line:4.5+i,price,reasoning:'Current role and matchup support the line.',confidence:'Medium',probability:.6,notes:''}))};}
test('American odds conversion and parlay combination are deterministic',()=>{const e=setup();assert.equal(e.run('americanToDecimal_(-200)'),1.5);assert.equal(e.run('americanToDecimal_(150)'),2.5);assert.equal(e.run('decimalToAmerican_(3)'),200);assert.equal(e.run('combineAmericanOdds_([-200,-200,-300])'),200);assert.equal(e.run('combineAmericanOdds_([-100,100,-200])'),500);assert.throws(()=>e.run('americanToDecimal_(99)'));});
test('2 through 5 legs validate (3 is the default, not a limit); out-of-range and duplicate legs fail',()=>{const e=setup();e.ctx.d2=draft([-100,-100]);e.ctx.d3=draft([-200,-200,-300]);e.ctx.d4=draft([-200,-200,-200,-200]);e.ctx.d5=draft([-300,-300,-300,-300,-300]);assert.equal(e.run('validateParlay_(d2).legs.length'),2);assert.equal(e.run('validateParlay_(d3).legs.length'),3);assert.equal(e.run('validateParlay_(d4).legs.length'),4);assert.equal(e.run('validateParlay_(d5).legs.length'),5);e.ctx.d1=draft([-150]);assert.throws(()=>e.run('validateParlay_(d1)'));e.ctx.d6=draft([-150,-150,-150,-150,-150,-150]);assert.throws(()=>e.run('validateParlay_(d6)'));e.ctx.dupe=draft([-200,-200,-300]);e.ctx.dupe.legs[1]={...e.ctx.dupe.legs[0]};assert.throws(()=>e.run('validateParlay_(dupe)'));});
test('+200 and +500 boundaries are accepted; outside range is rejected',()=>{const e=setup();e.ctx.low=draft([-200,-200,-300]);e.ctx.high=draft([-100,100,-200]);assert.equal(e.run('validateParlay_(low).combined'),200);assert.equal(e.run('validateParlay_(high).combined'),500);e.ctx.tooLow=draft([-200,-200,-310]);e.ctx.tooHigh=draft([-100,100,-190]);assert.throws(()=>e.run('validateParlay_(tooLow)'));assert.throws(()=>e.run('validateParlay_(tooHigh)'));});
test('stable IDs are persisted and exact duplicate submissions are blocked',()=>{const e=setup();e.ctx.d=e.run('validateParlay_('+JSON.stringify(draft([-200,-200,-300]))+')');const saved=e.run('saveParlay_(d,"2026-09-09T14:00:00.000Z")');assert.match(saved.parlayId,/^P-[A-F0-9]{16}$/);assert.equal(e.sheet('PARLAYS').data.length,2);assert.equal(e.sheet('LEGS').data.length,4);assert.equal(e.sheet('LEGS').data[1][1],saved.parlayId);assert.throws(()=>e.run('saveParlay_(d,"2026-09-09T14:01:00.000Z")'),/already locked/);});
test('grading waits for all legs and handles win, loss, push, void',()=>{const e=setup();e.ctx.p=['P1','', '', '',3,200,10,30,'PENDING','',''];const leg=(s,i)=>{const r=Array(20).fill('');r[2]=i;r[9]=100;r[17]=s;return r;},legs=(...s)=>s.map((x,i)=>leg(x,i+1));e.ctx.a=legs('WIN','WIN','WIN');e.ctx.b=legs('WIN','PUSH','WIN');e.ctx.c=legs('WIN','LOSS','PUSH');e.ctx.d=legs('VOID','PUSH','VOID');e.ctx.x=legs('WIN','PENDING','LOSS');assert.deepEqual(JSON.parse(e.run('JSON.stringify(gradeOneParlay_(p,a,"T"))')),{status:'WIN',settled:'T',profit:70});assert.deepEqual(JSON.parse(e.run('JSON.stringify(gradeOneParlay_(p,b,"T"))')),{status:'WIN',settled:'T',profit:30});assert.deepEqual(JSON.parse(e.run('JSON.stringify(gradeOneParlay_(p,c,"T"))')),{status:'LOSS',settled:'T',profit:-10});assert.deepEqual(JSON.parse(e.run('JSON.stringify(gradeOneParlay_(p,d,"T"))')),{status:'VOID',settled:'T',profit:0});assert.deepEqual(JSON.parse(e.run('JSON.stringify(gradeOneParlay_(p,x,"T"))')),{status:'PENDING',settled:'',profit:''});assert.throws(()=>e.run('gradeOneParlay_(p,a.slice(0,2),"T")'));});
test('grading accepts historical 2, 4, and 5 leg parlays; rejects out-of-range expected counts',()=>{const e=setup();const leg=(s,i)=>{const r=Array(20).fill('');r[2]=i;r[9]=100;r[17]=s;return r;};e.ctx.p2=['P2','','','',2,150,10,25,'PENDING','',''];e.ctx.legs2=[leg('WIN',1),leg('WIN',2)];assert.equal(e.run('gradeOneParlay_(p2,legs2,"T").status'),'WIN');e.ctx.p4=['P4','','','',4,300,10,40,'PENDING','',''];e.ctx.legs4=[leg('WIN',1),leg('WIN',2),leg('WIN',3),leg('WIN',4)];assert.equal(e.run('gradeOneParlay_(p4,legs4,"T").status'),'WIN');e.ctx.p5=['P5','','','',5,400,10,50,'PENDING','',''];e.ctx.legs5=[leg('WIN',1),leg('WIN',2),leg('WIN',3),leg('WIN',4),leg('WIN',5)];assert.equal(e.run('gradeOneParlay_(p5,legs5,"T").status'),'WIN');e.ctx.pBad=['PB','','','',6,400,10,50,'PENDING','',''];e.ctx.legsBad=[leg('WIN',1),leg('WIN',2),leg('WIN',3),leg('WIN',4),leg('WIN',5),leg('WIN',6)];assert.throws(()=>e.run('gradeOneParlay_(pBad,legsBad,"T")'));});
test('PERFORMANCE breaks resolved legs out by leg count',()=>{const e=setup(),lh=e.run('LEG_HEADERS.slice()'),ph=e.run('PARLAY_HEADERS.slice()');const leg=(id,parlayId,n)=>row(lh,{'Leg ID':id,'Parlay ID':parlayId,'Leg Number':n,'Market':'player_receptions','Side / Selection':'Over','American Price':-110,'Status':'WIN'});const parlay=(id,legCount)=>row(ph,{'Parlay ID':id,'Leg Count':legCount,'Stake':10,'Status':'PENDING','Combined American Odds':300});e.sheet('LEGS').data=[lh,leg('L1','P2',1),leg('L2','P2',2),leg('L3','P3',1),leg('L4','P3',2),leg('L5','P3',3)];e.sheet('PARLAYS').data=[ph,parlay('P2',2),parlay('P3',3)];e.run('showPerformance()');const perf=e.sheet('PERFORMANCE').data,labels=perf.map(r=>r[0]);assert.ok(labels.includes('BY LEG COUNT'));const section=perf.slice(labels.indexOf('BY LEG COUNT')+1);const twoLegRow=section.find(r=>r[0]==='2 legs'),threeLegRow=section.find(r=>r[0]==='3 legs');assert.equal(twoLegRow[1],2);assert.equal(threeLegRow[1],3);});
test('tracker save, grading, and performance use zero Odds API calls',()=>{const e=setup();e.ctx.d=e.run('validateParlay_('+JSON.stringify(draft([-200,-200,-300]))+')');e.run('saveParlay_(d,"2026-09-09T14:00:00.000Z")');e.run('gradeParlays()');e.run('showPerformance()');assert.equal(e.calls.length,0);assert.equal(e.sheet('PERFORMANCE').data[0][0],'NFL PARLAY PERFORMANCE');});

function row(headers,values){return headers.map(h=>values[h]??'');}
const schedHeaders=['game_id','season','game_type','week','away_team','away_score','home_team','home_score','result','total','status'];
const statHeaders=['player_id','player_name','player_display_name','season','week','season_type','game_id','team','opponent_team','completions','passing_yards','passing_tds','carries','rushing_yards','rushing_tds','receptions','receiving_yards','receiving_tds','special_teams_tds','def_tds','fumble_recovery_tds'];
function schedRow(status='FINAL',extra={}){return row(schedHeaders,{game_id:'2025_01_NE_SEA',season:2025,game_type:'REG',week:1,away_team:'NE',away_score:20,home_team:'SEA',home_score:24,result:4,total:44,status,...extra});}
function statRow(id,name,team,extra={}){return row(statHeaders,{player_id:id,player_name:name.split(' ').map(x=>x[0]).join('.')+'.'+name.split(' ').slice(-1),player_display_name:name,season:2025,week:1,season_type:'REG',game_id:'2025_01_NE_SEA',team,opponent_team:team==='NE'?'SEA':'NE',completions:0,passing_yards:0,passing_tds:0,carries:0,rushing_yards:0,rushing_tds:0,receptions:0,receiving_yards:0,receiving_tds:0,special_teams_tds:0,def_tds:0,fumble_recovery_tds:0,...extra});}
function dataset(headers,rows,name){return {headers,rows,asset:{id:'asset-'+name,name,url:'https://github.com/nflverse/nflverse-data/releases/download/mock/'+name+'.csv',updated:'2025-09-09T12:00:00Z'},fetched:'2025-09-09T12:01:00Z',cacheHit:false};}
const injuryHeaders=['season','season_type','game_type','team','week','gsis_id','position','full_name','first_name','last_name','report_primary_injury','report_status','practice_primary_injury','practice_secondary_injury','practice_status'];
function injuryRow(extra={}){return row(injuryHeaders,{season:2026,season_type:'REG',game_type:'REG',team:'NE',week:1,gsis_id:'',position:'WR',full_name:'Player One',first_name:'Player',last_name:'One',report_primary_injury:'',report_status:'',practice_primary_injury:'',practice_secondary_injury:'',practice_status:'Full Participation in Practice',...extra});}
function indexRow(eventId,home,away,kickoffIso){const r=Array(19).fill('');r[0]=eventId;r[13]=home;r[14]=away;r[15]=kickoffIso;return r;}

test('release discovery paginates and ignores unrelated releases and assets',()=>{const e=setup(),releases=Array.from({length:100},(_,i)=>({id:i+1,tag_name:'unrelated-'+i,name:'Other Data'})),assets=Array.from({length:100},(_,i)=>({id:i+1,name:'unrelated_'+i+'.csv',browser_download_url:'https://github.com/nflverse/nflverse-data/releases/download/other/unrelated_'+i+'.csv'}));e.queue.push({data:releases},{data:[{id:901,tag_name:'weekly-performance',name:'Player Statistics Weekly',updated_at:'2025-09-09T00:00:00Z'}]},{data:assets},{data:[{id:999,name:'weekly_player_statistics_for_2025.csv',browser_download_url:'https://github.com/nflverse/nflverse-data/releases/download/dynamic/weekly_player_statistics_for_2025.csv',updated_at:'2025-09-09T01:00:00Z'}]});const asset=e.run('discoverNflverseAsset_("PLAYER_STATS",2025,1)');assert.equal(asset.id,'999');assert.equal(e.calls.length,4);assert.match(e.calls[1],/page=2/);assert.match(e.calls[3],/page=2/);assert.ok(e.sheet('LOG').data.some(r=>String(r[4]).includes(asset.url)));});
test('asset discovery refuses an unpublished requested season instead of falling back',()=>{const e=setup();e.queue.push({data:[{id:901,tag_name:'stats-player',name:'Player Statistics Weekly',updated_at:'2026-09-09T00:00:00Z'}]},{data:[{id:998,name:'weekly_player_statistics_for_2025.csv',browser_download_url:'https://github.com/nflverse/nflverse-data/releases/download/dynamic/weekly_player_statistics_for_2025.csv'}]});assert.throws(()=>e.run('discoverNflverseAsset_("PLAYER_STATS",2026,1)'),/season 2026/);assert.equal(e.calls.length,2);});
test('schedule asset is discovered by release metadata and asset semantics',()=>{const e=setup();e.queue.push({data:[{id:77,tag_name:'league-calendar',name:'Schedules and Games',updated_at:'2025-09-09T00:00:00Z'}]},{data:[{id:78,name:'league_schedule_current.csv',browser_download_url:'https://github.com/nflverse/nflverse-data/releases/download/calendar/league_schedule_current.csv',updated_at:'2025-09-09T01:00:00Z'}]});assert.equal(e.run('discoverNflverseAsset_("SCHEDULE",2025,1).id'),'78');assert.equal(e.calls.length,2);});
test('parsed weekly data is cached for one hour in a hidden auditable sheet',()=>{const e=setup(),csv=[statHeaders,statRow('p1','Player One','NE',{receiving_yards:80})];e.queue.push({data:[{id:91,tag_name:'player-weekly-statistics',name:'Player Weekly Stats',updated_at:new Date().toISOString()}]},{data:[{id:92,name:'player_weekly_stats_2025.csv',browser_download_url:'https://github.com/nflverse/nflverse-data/releases/download/mock/player_weekly_stats_2025.csv',updated_at:new Date().toISOString()}]},{data:csv});assert.equal(e.run('loadNflverseWeekDataset_("PLAYER_STATS",2025,1).rows.length'),1);const calls=e.calls.length;assert.equal(e.run('loadNflverseWeekDataset_("PLAYER_STATS",2025,1).cacheHit'),true);assert.equal(e.calls.length,calls);assert.equal(e.sheet('NFLVERSE_CACHE').hidden,true);assert.equal(e.sheet('NFLVERSE_CACHE').data[0][0],'Cache Key');assert.ok(e.sheet('LOG').data.some(r=>r[2]==='HIT'||r[3]==='HIT'));});
test('CSV week filtering excludes preseason rows when regular-season rows exist',()=>{const e=setup(),h=['season','week','game_type','game_id'],table=[h,[2025,1,'PRE','pre'],[2025,1,'REG','reg']];e.ctx.table=table;const result=JSON.parse(e.run('JSON.stringify(filterCsvWeek_(table,"SCHEDULE",2025,1).rows)'));assert.equal(result.length,1);assert.equal(result[0][3],'reg');});
test('week validation accepts final status and rejects scheduled delayed postponed canceled and in-progress',()=>{const e=setup();e.ctx.stats=dataset(statHeaders,[statRow('p1','Player One','NE')],'stats');for(const status of ['SCHEDULED','DELAYED','POSTPONED','CANCELED','IN_PROGRESS']){e.ctx.schedule=dataset(schedHeaders,[schedRow(status)],'schedule');assert.throws(()=>e.run('validateCompletedWeek_(schedule,stats,2025,1)'),/not safely final/);}e.ctx.schedule=dataset(schedHeaders,[schedRow('FINAL')],'schedule');assert.equal(e.run('validateCompletedWeek_(schedule,stats,2025,1).statusColumn'),'status');});
test('missing explicit status requires consistent score evidence and full stat coverage',()=>{const e=setup(),h=schedHeaders.slice(0,-1);e.ctx.stats=dataset(statHeaders,[statRow('p1','Player One','NE')],'stats');e.ctx.schedule=dataset(h,[row(h,{game_id:'2025_01_NE_SEA',season:2025,game_type:'REG',week:1,away_team:'NE',away_score:20,home_team:'SEA',home_score:24,result:4,total:44})],'schedule');assert.equal(e.run('validateCompletedWeek_(schedule,stats,2025,1).statusColumn'),'');e.ctx.schedule.rows[0][h.indexOf('away_score')]='';assert.throws(()=>e.run('validateCompletedWeek_(schedule,stats,2025,1)'));e.ctx.schedule.rows[0][h.indexOf('away_score')]=20;e.ctx.stats.rows=[];assert.throws(()=>e.run('validateCompletedWeek_(schedule,stats,2025,1)'),/missing player-stat coverage/);});
test('two-game week refuses partial completion or missing game-level stats coverage',()=>{const e=setup(),second=schedRow('FINAL',{game_id:'2025_01_SF_LA',away_team:'SF',away_score:17,home_team:'LA',home_score:21,result:4,total:38});e.ctx.schedule=dataset(schedHeaders,[schedRow('FINAL'),second],'schedule');e.ctx.stats=dataset(statHeaders,[statRow('p1','Player One','NE')],'stats');assert.throws(()=>e.run('validateCompletedWeek_(schedule,stats,2025,1)'),/2025_01_SF_LA missing player-stat coverage/);e.ctx.schedule.rows[1][schedHeaders.indexOf('status')]='DELAYED';assert.throws(()=>e.run('validateCompletedWeek_(schedule,stats,2025,1)'),/status DELAYED/);});
test('name normalization handles Unicode punctuation whitespace and suffixes',()=>{const e=setup();assert.equal(e.run('normPlayerName_("  D’André-Swift Jr. ")'),'dandre swift');assert.equal(e.run('normPlayerName_("Marvin Harrison III")'),'marvin harrison');});
test('identity resolution supports exact safe fuzzy ambiguous unmatched and manual maps',()=>{const e=setup(),rows=[statRow('p1','Justin Jefferson','MIN'),statRow('p2','Justin Jeffersom','GB'),statRow('p3','John Smith','NE'),statRow('p4','John Smith','NE')];rows.forEach(r=>r[statHeaders.indexOf('game_id')]='g1');e.ctx.rows=rows;e.ctx.h=statHeaders;e.run('var pm=headerMap_(h,[]);var game={gameId:"g1"}');assert.equal(e.run('resolvePlayer_("Justin Jefferson","MIN",game,rows,pm,{}).method'),'EXACT');assert.match(e.run('resolvePlayer_("Justin Jeffersom","MIN",game,rows,pm,{}).method'),/^FUZZY/);assert.equal(e.run('resolvePlayer_("John Smith","NE",game,rows,pm,{}).reason'),'AMBIGUOUS_EXACT_NAME');assert.equal(e.run('resolvePlayer_("Nobody Here","NE",game,rows,pm,{}).reason'),'UNMATCHED_NAME');e.ctx.exceptions=[[2025,1,'Alias Player','MIN','','','', 'p1','RESOLVED','','','L1']];e.run('var manual=manualMappings_(exceptions)');assert.equal(e.run('resolvePlayer_("Alias Player","MIN",game,rows,pm,manual).method'),'MANUAL');});
test('EXCEPTIONS upsert preserves user manual mapping and resolution fields',()=>{const e=setup(),existing=[2025,1,'Alias Player','NE','New England Patriots @ Seattle Seahawks','old','UNMATCHED_NAME','manual-p1','RESOLVED','created','old-update','L1'];e.sheet('EXCEPTIONS').data=[e.run('EXCEPTION_HEADERS.slice()'),existing];e.ctx.items=[{season:2025,week:1,name:'Alias Player',team:'NE',game:'New England Patriots @ Seattle Seahawks',candidates:'new candidates',reason:'UNMATCHED_NAME',legId:'L1'}];e.run('upsertExceptions_(items,"new-update")');const saved=e.sheet('EXCEPTIONS').data[1];assert.equal(saved[7],'manual-p1');assert.equal(saved[8],'RESOLVED');assert.equal(saved[9],'created');assert.equal(saved[5],'new candidates');});
test('grading headers extend by name without reordering existing columns',()=>{const e=setup(),old=['Status','Leg ID','Market','Parlay ID','Event ID','Event / Game','Player / Team','Side / Selection','Line','Actual Stat / Score'];e.sheet('LEGS').data=[old,['PENDING','L1','player_receptions','P1','e1','A @ B','Player','Over',3.5,'']];const headers=JSON.parse(e.run('JSON.stringify(compatibleHeaders_(TAB_LEGS,LEG_HEADERS).headers)'));assert.deepEqual(headers.slice(0,old.length),old);assert.ok(headers.includes('nflverse Player ID'));assert.equal(e.sheet('LEGS').data[1][1],'L1');});
test('required markets settle over under win loss and equality push',()=>{const e=setup(),r=statRow('p1','Player One','NE',{receiving_yards:80,rushing_yards:40,passing_yards:250,receptions:4,passing_tds:2,completions:20,carries:10});e.ctx.r=r;e.ctx.h=statHeaders;e.run('var pm=headerMap_(h,[])');const cases=[['player_receiving_yards','Over',75.5,'WIN'],['player_reception_yds','Under',75.5,'LOSS'],['player_rushing_yards','Under',50.5,'WIN'],['player_rush_yds','Over',50.5,'LOSS'],['player_passing_yards','Over',250,'PUSH'],['player_pass_yds','Under',250,'PUSH'],['player_receptions','Over',3.5,'WIN'],['player_pass_tds','Under',1.5,'LOSS'],['player_pass_completions','Over',19.5,'WIN'],['player_rush_attempts','Under',10,'PUSH'],['player_rush_reception_yds','Over',119.5,'WIN']];for(const [market,side,line,result] of cases){e.ctx.market=market;e.ctx.side=side;e.ctx.line=line;assert.equal(e.run('marketSettlement_(market,r,pm,side,line,"Player One").result'),result);}});
test('anytime TD excludes passing TDs and includes available non-passing return TD columns',()=>{const e=setup(),r=statRow('p1','Player One','NE',{passing_tds:4});e.ctx.r=r;e.ctx.h=statHeaders;e.run('var pm=headerMap_(h,[])');assert.equal(e.run('marketSettlement_("player_anytime_td",r,pm,"Yes","","Player One").result'),'LOSS');r[statHeaders.indexOf('special_teams_tds')]=1;assert.equal(e.run('marketSettlement_("player_anytime_td",r,pm,"Player One","","Player One").result'),'WIN');r[statHeaders.indexOf('special_teams_tds')]=0;r[statHeaders.indexOf('fumble_recovery_tds')]=1;assert.equal(e.run('marketSettlement_("player_anytime_td",r,pm,"Yes","","Player One").result'),'WIN');assert.match(e.run('marketSettlement_("player_anytime_td",r,pm,"Over","","Player One").error'),/UNSUPPORTED_ATD_SIDE/);e.run('delete pm.special_teams_tds');assert.match(e.run('marketSettlement_("player_anytime_td",r,pm,"Yes","","Player One").error'),/ATD_COVERAGE_INCOMPLETE/);});
test('unsupported markets return an explicit exception reason instead of a guess',()=>{const e=setup();e.ctx.r=statRow('p1','Player One','NE');e.ctx.h=statHeaders;e.run('var pm=headerMap_(h,[])');assert.match(e.run('marketSettlement_("player_unknown_prop",r,pm,"Over",1,"Player One").error'),/^UNSUPPORTED_MARKET/);});

