test('ticking manual confirm writes against the leg (not ROSTER) and stamps it once, without overwriting on rerun',()=>{
  const {e,lh,rh,leg,roster}=availabilityFixture_();
  e.sheet('LEGS').data=[lh,leg({'Manual Availability Confirm':true})];
  e.sheet('ROSTER').data=[rh,roster({game_status:'OUT',status_source:'INJURY_REPORT'})];
  let result=e.run('runAvailabilityGate()');
  assert.equal(result.confirmed,1);assert.equal(result.cleared,1);assert.equal(result.blocked,0);
  const gi=Object.fromEntries(lh.map((h,i)=>[h,i])),ri=Object.fromEntries(rh.map((h,i)=>[h,i]));
  // ROSTER is untouched by the confirmation — it is a leg-level fact only.
  assert.equal(e.sheet('ROSTER').data[1][ri.status_source],'INJURY_REPORT');
  const firstStamp=e.sheet('LEGS').data[1][gi['Manual Confirmed UTC']];
  assert.ok(firstStamp);
  assert.equal(e.sheet('LEGS').data[1][gi['Manual Confirmed Game Status']],'OUT');
  result=e.run('runAvailabilityGate()');
  assert.equal(result.confirmed,0);
  assert.equal(e.sheet('LEGS').data[1][gi['Manual Confirmed UTC']],firstStamp);
});
