test('a game status change after manual confirmation is flagged as a conflict, not silently kept',()=>{
  const {e,lh,rh,leg,roster}=availabilityFixture_();
  e.sheet('LEGS').data=[lh,leg({'Manual Availability Confirm':true})];
  e.sheet('ROSTER').data=[rh,roster({game_status:'QUESTIONABLE',status_source:'INJURY_REPORT'})];
  let result=e.run('runAvailabilityGate()');
  assert.equal(result.cleared,1);
  const gi=Object.fromEntries(lh.map((h,i)=>[h,i])),ri=Object.fromEntries(rh.map((h,i)=>[h,i]));
  assert.equal(e.sheet('LEGS').data[1][gi['Manual Confirmed Game Status']],'QUESTIONABLE');
  // A fresh pull moves the player from Questionable to Out after confirmation.
  e.sheet('ROSTER').data[1][ri.game_status]='OUT';
  result=e.run('runAvailabilityGate()');
  assert.equal(result.blocked,1);assert.equal(result.cleared,0);
  assert.equal(e.sheet('LEGS').data[1][gi['Availability Gate']],'BLOCKED');
  assert.match(e.sheet('LEGS').data[1][gi['Availability Gate Detail']],/QUESTIONABLE.*OUT|conflict|Re-check/i);
  // The confirmation timestamp itself is preserved as a record, not erased.
  assert.ok(e.sheet('LEGS').data[1][gi['Manual Confirmed UTC']]);
});
